//   outputs (MSB first): busy[1] done[1] res_data[20] res_data4[80]
`timescale 1ns/1ps
module replay_itx2d;
    localparam int NI = 60;
    localparam int NO = 102;
    localparam int MAXV = 400000;
    logic [NI-1:0] vin [0:MAXV-1];
    logic [NO-1:0] vout [0:MAXV-1];
    logic clk = 0;
    logic rst;
    logic coef_clr;
    logic coef_we;
    logic [9:0] coef_addr;
    logic [19:0] coef_data;
    logic start;
    logic [4:0] tx_sz;
    logic [3:0] tx_type;
    logic [3:0] bit_depth;
    logic lossless;
    logic [11:0] res_addr;
    logic busy;
    logic done;
    logic [19:0] res_data;
    logic [79:0] res_data4;
`ifdef NETLIST
    // the funcsim netlist flattens struct ports into one port per leaf field
    itx2d dut (.clk(clk), .rst(rst), .coef_clr(coef_clr), .coef_we(coef_we), .coef_addr(coef_addr), .coef_data(coef_data), .start(start), .tx_sz(tx_sz), .tx_type(tx_type), .bit_depth(bit_depth), .lossless(lossless), .res_addr(res_addr), .busy(busy), .done(done), .res_data(res_data), .res_data4(res_data4));
`else
    itx2d dut (.*);
`endif
    int n, errs, cmp, xmask, preroll;
    string vecfile;
    initial begin
        if (!$value$plusargs("vec=%s", vecfile)) vecfile = "vectors.hex";
        if (!$value$plusargs("xmask=%d", xmask)) xmask = 0;    // 1: X bits of the DUT are don't-care (RTL control)
        if (!$value$plusargs("preroll=%d", preroll)) preroll = 15;   // cycles of vector 0 before the replay: the
                                                                     // funcsim netlist holds GSR for the first 100 ns
        for (int i = 0; i < MAXV; i++) vin[i] = 'x;
        $readmemh(vecfile, vin, 0, MAXV-1);
        $readmemh({vecfile, ".out"}, vout, 0, MAXV-1);
    end
    function automatic logic [NO-1:0] xbits(input logic [NO-1:0] v);   // 1 where v is X or Z
        for (int b = 0; b < NO; b++) xbits[b] = (v[b] === 1'bx || v[b] === 1'bz);
    endfunction
    initial begin
        errs = 0; cmp = 0; n = 0;
        for (int i = 0; i < preroll; i++) begin
            {rst, coef_clr, coef_we, coef_addr, coef_data, start, tx_sz, tx_type, bit_depth, lossless, res_addr} = vin[0];
            #5 clk = 1; #5 clk = 0;
        end
        while (n < MAXV && vin[n] !== 'x) begin
            {rst, coef_clr, coef_we, coef_addr, coef_data, start, tx_sz, tx_type, bit_depth, lossless, res_addr} = vin[n];
            #4;
            if (n > 2) begin
                cmp++;
                if (xmask ? ((({busy, done, res_data, res_data4} ^ vout[n]) & ~xbits({busy, done, res_data, res_data4})) !== '0)
                          : (busy !== vout[n][101:101] || done !== vout[n][100:100] || res_data !== vout[n][99:80] || res_data4 !== vout[n][79:0])) begin
                    errs++;
                    if (errs <= 100000) $display("MISMATCH cycle %0d: got %h exp %h", n, {busy, done, res_data, res_data4}, vout[n]);
                end
            end
            #1 clk = 1; #5 clk = 0;
            n++;
        end
        $display("REPLAY %s: %0d cycles, %0d compared, %0d mismatches -> %s", vecfile, n, cmp, errs, errs == 0 ? "PASS" : "FAIL");
        $finish;
    end
endmodule

